+fn with_conditions(conds: &str) -> String {
+    let mut v: serde_json::Value = serde_json::from_str(WIRE).expect("template json");
+    v["edm"]["conditions"] = serde_json::from_str(conds).expect("conditions json");
+    v.to_string()
