+const TABLE: &str = r#"[
+    { "id": "C110", "name": "rough", "gap": 0.04, "wire_diameter": 0.25, "role": "rough" },
+    { "id": "330", "wire_diameter": 0.25, "role": "finish" },
+    { "id": "S9", "gap": 0.02, "undersize": 0.1 }
