+    for m in [Kind::Mill, Kind::Lathe, Kind::MillTurn, Kind::Plasma, Kind::SinkerEdm] {
+        assert!(!operation::shown_for(m).contains(&Section::WireEdm), "{m:?}");
+        assert!(!info.admits(m), "{m:?}");
