+    let op = WireContourOp {
+        top_z: Height::fixed(12.0),
+        bottom_z: Height::fixed(0.0),
+        condition: "C110".into(),
+        side,
+        start: None,
+        clearance: operation::DEFAULT_CLEARANCE,
